// A simple lambda for comparison
auto derefLessAuto = [](const auto& p1, const auto& p2) {
    return *p1 < *p2;
};
// Type of derefLessAuto is the unique closure type. Size is minimal.
// Calls are direct and likely to be inlined.

#include <functional>
#include <memory>
#include <vector>

std::function<bool(const std::unique_ptr<int>&, const std::unique_ptr<int>&)>
  derefLessFunc = [](const auto& p1, const auto& p2) {
    return *p1 < *p2;
};
// Type is std::function, which is a wrapper.
// Size is fixed and larger; may cause heap allocation for the closure.
// Calls are indirect, less likely to be inlined.
